def transform(grid):
    g = np.array(grid)
    n = g.shape[0]
    c = int(g[0, 0])
    size = 15
    out = np.zeros((size, size), dtype=int)
    emit(out, f"Allocate a 15x15 black canvas; the input is a {n}x{n} block of colour {c}, so the lattice period is {n+1}.")
    for y in range(size):
        if y % (n + 1) == n:
            out[y, :] = c
    emit(out, f"Draw full horizontal lines of colour {c} at every row y with y % {n+1} == {n}.")
    for x in range(size):
        if x % (n + 1) == n:
            out[:, x] = c
    emit(out, f"Draw full vertical lines of colour {c} at every column x with x % {n+1} == {n}, leaving {n}x{n} black cells between lines.")
    return out
